import{_ as n,o as t,c as r,a6 as i}from"./chunks/framework.DNkVJs23.js";const g=JSON.parse('{"title":"Datenschutz","description":"Datenschutz — Sapphire Star Codex","frontmatter":{"description":"Datenschutz — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/de/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/de/privacy/"}],["meta",{"property":"og:title","content":"Datenschutz | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Datenschutz — Sapphire Star Codex"}]]},"headers":[],"relativePath":"de/privacy/index.md","filePath":"de/privacy/index.md"}'),a={name:"de/privacy/index.md"};function s(u,e,h,o,d,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to &quot;Datenschutz&quot;">​</a></h1><p>Gültig seit: 31. Oktober 2026. Letzte Änderung des Ausgangstexts: 10. November 2026. Übersetzung: 14. November 2026.</p><p>Diese Richtlinie gilt für die iOS-, Android- und HarmonyOS-Apps von Sapphire Star Codex sowie diese Website. Entwickler: <strong>eurekaffeine (刘耀晨)</strong>. Kontakt: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Funktionen unterscheiden sich je nach Plattform; ein Konto ist nicht erforderlich.</p><h2 id="lokale-daten" tabindex="-1">Lokale Daten <a class="header-anchor" href="#lokale-daten" aria-label="Permalink to &quot;Lokale Daten&quot;">​</a></h2><p>Die App speichert Spiel-, Sprach- und Darstellungseinstellungen, Suchverlauf und Navigationszustand, Favoriten, gespeicherte Sets samt Namen sowie Bestände an Dekorationen, Talismanen und Rüstung auf dem Gerät. Diese Daten ermöglichen die App-Funktionen und werden nicht an den Entwickler hochgeladen. Der Entwickler betreibt weder Konten noch eine Cloud-Synchronisierung.</p><h2 id="berechtigungen-und-automatische-erfassung" tabindex="-1">Berechtigungen und automatische Erfassung <a class="header-anchor" href="#berechtigungen-und-automatische-erfassung" aria-label="Permalink to &quot;Berechtigungen und automatische Erfassung&quot;">​</a></h2><p>Die App enthält keine SDKs für Werbung, Tracking, Nutzungsstatistiken oder automatische Absturzberichte. Ihre aktuellen Funktionen benötigen keinen Zugriff auf Kontakte, Standort, Kamera, Mikrofon oder Fotos und erfassen keine Werbe-ID. Betriebssystem und Stores können Installations- oder Diagnosedaten nach eigenen Regeln verarbeiten. Vom Anbieter übermittelte Diagnosen nutzt der Entwickler nur zur Fehlerbehebung.</p><h2 id="kontakt-und-externe-dienste" tabindex="-1">Kontakt und externe Dienste <a class="header-anchor" href="#kontakt-und-externe-dienste" aria-label="Permalink to &quot;Kontakt und externe Dienste&quot;">​</a></h2><p>Bei freiwilligem E-Mail-Kontakt erhält der Entwickler deine Adresse, Nachricht und Anhänge, um zu antworten, Fehler zu untersuchen und Datenschutzanfragen zu bearbeiten; nicht für Marketing. Sende nur notwendige Angaben. Gmail verarbeitet E-Mails gemäß der <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google-Datenschutzerklärung</a>.</p><p>Diese Website wird von GitHub Pages gehostet. Dabei können IP-Adresse und technische Browserangaben anfallen; siehe <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">GitHub-Datenschutzerklärung</a>. Es werden keine Besucherstatistik, Werbe-Cookies oder Tracking-Pixel hinzugefügt. Die Suche läuft im Browser; Einstellungen können dort gespeichert werden. Externe Dienste haben eigene Richtlinien und können Daten außerhalb deines Landes verarbeiten.</p><h2 id="beitrage-und-sicherungen" tabindex="-1">Beiträge und Sicherungen <a class="header-anchor" href="#beitrage-und-sicherungen" aria-label="Permalink to &quot;Beiträge und Sicherungen&quot;">​</a></h2><p>Alipay oder WeChat Pay verarbeitet freiwillige Beiträge nach eigenen Bedingungen. Die Website zeigt nur statische Codes, ohne Zahlungs-SDK oder Empfang von Zugangsdaten. Der Entwickler kann Angaben sehen, die die Plattform dem Empfänger zeigt, etwa Betrag, Zeitpunkt, Anzeigename und Mitteilung. Sie dienen der Zuordnung und Problemlösung und unterliegen den Aufbewahrungsregeln der Plattform und gesetzlichen Pflichten. App-Daten können je nach Systemeinstellung in Geräte- oder Cloud-Sicherungen enthalten sein. Der Entwickler kann solche Sicherungen weder lesen noch löschen.</p><h2 id="weitergabe-aufbewahrung-und-loschung" tabindex="-1">Weitergabe, Aufbewahrung und Löschung <a class="header-anchor" href="#weitergabe-aufbewahrung-und-loschung" aria-label="Permalink to &quot;Weitergabe, Aufbewahrung und Löschung&quot;">​</a></h2><p>Der Entwickler verkauft oder vermietet keine personenbezogenen Daten und gibt sie nicht für Werbung weiter. E-Mails werden vom genannten Anbieter verarbeitet. Tatsächlich vorhandene Informationen können bei gesetzlicher Pflicht oder auf ausdrückliche Anfrage weitergegeben werden.</p><p>Lokale Daten lassen sich über App- oder Systemeinstellungen löschen. Deinstallationen mit Datenerhalt löschen sie nicht; Sicherungen sind separat zu verwalten und können Daten später wiederherstellen. Website-Einstellungen bleiben bis zur Löschung oder automatischen Browserbereinigung. Nachrichten werden nur so lange gespeichert, wie Bearbeitung, Nachfragen oder Rechtspflichten es erfordern. Dienstanbieter verwalten eigene Protokolle und Sicherungen. Kontaktiere uns für Auskunft, Berichtigung oder Löschung übermittelter Angaben; gesetzliche Aufbewahrungspflichten bleiben bestehen. Nur auf dem Gerät gespeicherte Daten sind für den Entwickler nicht aus der Ferne zugänglich.</p><h2 id="sicherheit-minderjahrige-und-anderungen" tabindex="-1">Sicherheit, Minderjährige und Änderungen <a class="header-anchor" href="#sicherheit-minderjahrige-und-anderungen" aria-label="Permalink to &quot;Sicherheit, Minderjährige und Änderungen&quot;">​</a></h2><p>Lokale Daten sind durch die Speichermechanismen des Betriebssystems geschützt. Die Website verwendet HTTPS. Nachrichten werden nur für Support und Datenschutz bearbeitet; dabei gelten die Schutzmaßnahmen des E-Mail-Anbieters. Die App fragt weder persönliche Profile noch Geburtsdaten ab und erhebt nicht bewusst Daten von Kindern. Eltern können um Löschung von Angaben bitten, die ein Kind übermittelt hat.</p><p>Ändern sich die Verarbeitungspraktiken, werden Richtlinie und Datum angepasst. Wesentliche Änderungen werden auf der Website oder in App-Updates angekündigt. Erforderliche Berechtigungen oder Einwilligungen für neue Funktionen werden separat eingeholt; diese Richtlinie erteilt sie nicht.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const p=n(a,[["render",s]]);export{g as __pageData,p as default};
